function render({width,state,params}) {
  function integer(v,d,lo,hi) { const z=Number(v); return Number.isFinite(z)?Math.max(lo,Math.min(hi,Math.round(z))):d; }
  const W=integer(width,320,320,760), H=260;
  const k=integer(params&&params.kernel,3,2,5), n=5, j=2;
  const total=k-1, left=Math.ceil(total/2), right=Math.floor(total/2);
  const N=n+total, start=j-left, end=start+k-1, center=(start+end)/2;
  const focus=state==='center'?'center':'padding';
  const wide=W>=560, area=wide?W-190:W;
  const cell=Math.min(44,(area-32)/9), x=(area-N*cell)/2;
  const inputY=44, outputY=178;
  const ink='#252521', quiet='#a9a69e', blue='#3176a6', orange='#bb702e';
  const parts=[];
  function text(a,b,t,size,color,anchor) { parts.push('<text x="'+a+'" y="'+b+'" font-size="'+(size||14)+'" fill="'+(color||ink)+'" text-anchor="'+(anchor||'middle')+'">'+t+'</text>'); }
  function line(a,b,c,d,color,dash) { parts.push('<line x1="'+a+'" y1="'+b+'" x2="'+c+'" y2="'+d+'" stroke="'+color+'" stroke-width="1.5"'+(dash?' stroke-dasharray="4 3"':'')+'/>'); }
  function rect(a,b,w,h,fill,stroke,dash) { parts.push('<rect x="'+a+'" y="'+b+'" width="'+w+'" height="'+h+'" fill="'+fill+'" stroke="'+stroke+'"'+(dash?' stroke-dasharray="3 3"':'')+'/>'); }
  const sub=['₀','₁','₂','₃','₄'];
  text(x,25,'输入 X',15,ink,'start');
  const inputCells=[];
  for(let t=0;t<N;t++) {
    const coordinate=t-left, pad=coordinate<0||coordinate>=n;
    const inWindow=coordinate>=start&&coordinate<=end;
    rect(x+t*cell,inputY,cell,cell,inWindow?'#e0edf5':(pad?'#f0eeea':'#faf9f6'),pad?quiet:ink,pad);
    text(x+(t+0.5)*cell,inputY+cell/2+5,pad?'0':'x'+sub[coordinate],14);
    text(x+(t+0.5)*cell,inputY+cell+19,String(coordinate),14,quiet);
    inputCells.push({coordinate:coordinate,padding:pad,label:pad?'0':'x'+sub[coordinate],inWindow:inWindow});
  }
  const wx=x+j*cell, span=k*cell, mid=wx+span/2;
  rect(wx,inputY,span,cell,'none',blue,false);
  const by=112;
  line(wx,by,wx+span,by,blue,false);
  line(wx,by-5,wx,by+5,blue,false);
  line(wx+span,by-5,wx+span,by+5,blue,false);
  line(mid,by,mid,125,blue,false);
  parts.push('<circle cx="'+mid+'" cy="125" r="3" fill="'+blue+'"/>');
  text(mid,146,'窗口中心 '+center,14,blue);
  const ox=x+left*cell;
  text(ox,167,'输出 Y',15,ink,'start');
  const outputCells=[];
  for(let q=0;q<n;q++) {
    rect(ox+q*cell,outputY,cell,cell,q===j?'#f5e7d8':'#faf9f6',q===j?orange:quiet,false);
    text(ox+(q+0.5)*cell,outputY+cell/2+5,'y'+sub[q],14,q===j?orange:ink);
    outputCells.push({index:q,selected:q===j});
  }
  const selectedX=ox+(j+0.5)*cell;
  if(focus==='center') {
    line(selectedX,inputY-5,selectedX,inputY+cell+4,orange,true);
    line(selectedX,151,selectedX,outputY-4,orange,true);
  }
  if(wide) {
    const sx=W-174;
    text(sx,65,'k = '+k,16,ink,'start');
    text(sx,98,'p总 = '+total,16,ink,'start');
    text(sx,131,'左 '+left+' / 右 '+right,16,ink,'start');
    text(sx,164,'Y['+j+']：坐标 '+j,14,orange,'start');
    text(sx,197,'中心差 '+(center-j),14,blue,'start');
  } else {
    text(W/2,246,'k='+k+' · p总='+total+' · 左 '+left+' / 右 '+right,14);
  }
  const svg='<svg xmlns="http://www.w3.org/2000/svg" width="'+W+'" height="'+H+'" viewBox="0 0 '+W+' '+H+'" role="img"><title>核大小与中心对齐</title><desc>固定输入长度为五、步幅为一。核大小为'+k+'，总填充为'+total+'，左侧'+left+'，右侧'+right+'。输出索引二的窗口覆盖输入坐标'+start+'到'+end+'，几何中心为'+center+'。</desc><rect width="'+W+'" height="'+H+'" fill="#faf9f6"/><g font-family="sans-serif">'+parts.join('')+'</g></svg>';
  return {svg:svg,facts:{state:focus,width:W,height:H,inputLength:n,kernelSize:k,stride:1,dilation:1,padding:{total:total,left:left,right:right},paddedLength:N,outputLength:N-k+1,selectedOutputIndex:j,window:{inputStart:start,inputEnd:end,center:center,offsetFromOutputIndex:center-j},inputCells:inputCells,outputCells:outputCells,geometry:{cellSize:cell,inputOriginX:x,inputY:inputY,outputOriginX:ox,outputY:outputY},numericConvolutionComputed:false}};
}

function render({width,state,params}) {
  function integer(v,d,lo,hi) { const z=Number(v); return Number.isFinite(z)?Math.max(lo,Math.min(hi,Math.round(z))):d; }
  const W=integer(width,320,320,760), H=268;
  const s=integer(params&&params.stride,2,1,3);
  const p=integer(params&&params.rightPadding,0,0,2);
  const n=5,k=2,N=n+p,count=Math.floor((N-k)/s)+1;
  const origins=Array.from({length:count},function(_,i){return i*s;});
  const next=count*s, wide=W>=560;
  const area=wide?W*0.6:W, cell=Math.min(40,(area-32)/8);
  const x=wide?16:(W-8*cell)/2, y=42;
  const ink='#252521',quiet='#a9a69e',blue='#3176a6',orange='#bb702e';
  const parts=[];
  function text(a,b,t,size,color,anchor) { parts.push('<text x="'+a+'" y="'+b+'" font-size="'+(size||14)+'" fill="'+(color||ink)+'" text-anchor="'+(anchor||'middle')+'">'+t+'</text>'); }
  function line(a,b,c,d,color,dash) { parts.push('<line x1="'+a+'" y1="'+b+'" x2="'+c+'" y2="'+d+'" stroke="'+color+'" stroke-width="2"'+(dash?' stroke-dasharray="4 3"':'')+'/>'); }
  function rect(a,b,w,h,fill,stroke,dash) { parts.push('<rect x="'+a+'" y="'+b+'" width="'+w+'" height="'+h+'" fill="'+fill+'" stroke="'+stroke+'"'+(dash?' stroke-dasharray="3 3"':'')+'/>'); }
  const sub=['₀','₁','₂','₃','₄','₅'];
  text(x,24,'输入 n=5',15,ink,'start');
  text(x+8*cell,24,'右填充 '+p,14,ink,'end');
  const inputCells=[];
  for(let q=0;q<N;q++) {
    const padded=q>=n;
    rect(x+q*cell,y,cell,cell,padded?'#f0eeea':'#faf9f6',padded?quiet:ink,padded);
    text(x+(q+0.5)*cell,y+cell/2+5,padded?'0':'x'+sub[q],14);
    inputCells.push({paddedIndex:q,padding:padded,label:padded?'0':'x'+sub[q]});
  }
  for(let q=0;q<8;q++) text(x+(q+0.5)*cell,y+cell+18,String(q),14,quiet);
  const boundary=x+N*cell;
  line(boundary,y-5,boundary,165,quiet,true);
  const windows=[];
  for(let i=0;i<count;i++) {
    const a=origins[i], yy=114+(i%2)*20, xx=x+a*cell;
    rect(xx+1,yy,k*cell-2,7,'#dcebf5',blue,false);
    parts.push('<circle cx="'+(xx+cell/2)+'" cy="'+(yy+3.5)+'" r="2.5" fill="'+blue+'"/>');
    windows.push({outputIndex:i,start:a,endInclusive:a+k-1,startMultiple:i,stride:s,valid:a+k<=N,barY:yy});
  }
  const nx=x+next*cell;
  rect(nx+1,154,k*cell-2,7,'none',quiet,true);
  text(nx+k*cell/2,178,'越界',14,ink);
  const outCell=wide?Math.min(32,(W*0.35-24)/6):Math.min(36,(W-32)/6);
  const outX=wide?W*0.65:(W-count*outCell)/2;
  const outY=wide?77:200;
  text(outX,outY-10,'输出 Y',15,ink,'start');
  const outputCells=[];
  for(let i=0;i<count;i++) {
    rect(outX+i*outCell,outY,outCell,26,'#f5e7d8',orange,false);
    text(outX+(i+0.5)*outCell,outY+18,'y'+sub[i],14,orange);
    outputCells.push({outputIndex:i,inputStart:origins[i],inputEndInclusive:origins[i]+k-1});
  }
  if(wide) {
    text(outX,134,'s = '+s,15,ink,'start');
    text(outX,163,count+' 个合法起点',15,orange,'start');
  } else {
    text(W-16,190,count+' 格',14,orange,'end');
  }
  text(W/2,252,'⌊('+n+'+'+p+'−'+k+')/'+s+'⌋+1 = '+count,16);
  const svg='<svg xmlns="http://www.w3.org/2000/svg" width="'+W+'" height="'+H+'" viewBox="0 0 '+W+' '+H+'" role="img"><title>最后一个窗口能否放下</title><desc>固定输入长度五，核宽二，右侧填充'+p+'格，步幅'+s+'。合法窗口起点为'+origins.join('、')+'，对应'+count+'个输出。下一个起点'+next+'的窗口超出填充后长度'+N+'。</desc><rect width="'+W+'" height="'+H+'" fill="#faf9f6"/><g font-family="sans-serif">'+parts.join('')+'</g></svg>';
  return {svg:svg,facts:{state:'count',width:W,height:H,inputLength:n,kernelSize:k,stride:s,dilation:1,padding:{left:0,right:p,total:p},paddedLength:N,lastAllowedStart:N-k,validOrigins:origins,outputLength:count,windows:windows,nextWindow:{start:next,endInclusive:next+k-1,valid:next+k<=N,overflowCells:Math.max(0,next+k-N)},remainder:(N-k)%s,formulaOperands:{n:n,pTotal:p,k:k,s:s},inputCells:inputCells,outputCells:outputCells,geometry:{cellSize:cell,inputOriginX:x,inputY:y,boundaryX:boundary,outputCellWidth:outCell,outputOriginX:outX,outputY:outY},numericConvolutionComputed:false}};
}
